algorithms.pseudocode:
CANONICAL-TROPICAL-RECONSTRUCTION(num_participants, blocking_sets):
  d ← len(blocking_sets)
  M ← zeros(num_participants, d)
  for j = 0 to d-1:
    for p in blocking_sets[j]:
      M[p][j] ← 1
  τ ← ones(d)
  return (M, τ)

IS-AUTHORIZED(M, τ, C):
  for j = 0 to d-1:
    score ← max(M[p][j] for p in C)
    if score < τ[j]: return FALSE
  return TRUE

EXTRACT-MINIMAL(M, τ, C):
  D ← C
  for p in C:
    if IS-AUTHORIZED(M, τ, D \ {p}):
      D ← D \ {p}
  return D
